const config = $input.first().json;
const msg = $('Telegram Trigger').first().json.message;
const chatId = msg.chat.id;
const msgText = (msg.text || '').trim();

// Get today's date in Central Time (YYYY-MM-DD)
const now = new Date();
const today = now.toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });

// Handle empty message
if (!msgText) {
  return [{
    json: {
      chatId,
      action: 'empty',
      replyText: 'Please send a vendor name (e.g., "Costco", "Target", "Walgreens").'
    }
  }];
}

const defaultCity = (config.DefaultCity || '').trim();
const lastCheck = (config.LastCityCheck || '').trim();
const todayCity = (config.TodayCity || '').trim();
const pendingVendor = (config.PendingVendor || '').trim();
const pendingDate = (config.PendingDate || '').trim();

// Case 1: City already confirmed today
if (lastCheck === today && todayCity) {
  return [{
    json: {
      chatId,
      action: 'ready',
      searchName: msgText,
      dailyCity: todayCity
    }
  }];
}

// Case 2: There is a pending vendor query for today - this message is the city reply
if (pendingVendor && pendingDate === today) {
  const cityReply = (msgText.toLowerCase() === 'yes') ? defaultCity : msgText;
  return [{
    json: {
      chatId,
      action: 'city_reply',
      searchName: pendingVendor,
      dailyCity: cityReply,
      today: today
    }
  }];
}

// Case 3: First query of the day - need to ask for city
return [{
  json: {
    chatId,
    action: 'need_city',
    searchName: msgText,
    defaultCity: defaultCity,
    today: today,
    replyText: `\ud83d\udccd Are you in *${defaultCity}* today?\n\nReply *yes* to confirm, or send a different city (e.g., "Dallas, TX").`
  }
}];

const items = $input.all();
const dailyState = $('Check Daily State').first().json;
const chatId = dailyState.chatId;
const searchName = dailyState.searchName;
const dailyCity = dailyState.dailyCity;

// Validate input (safety net - should be caught earlier by Check Daily State)
if (!searchName) {
  return [{
    json: {
      chatId,
      status: 'empty',
      searchName: '',
      replyText: 'Please send a vendor name (e.g., "Costco", "Target", "Walgreens").'
    }
  }];
}

// Search for vendor (case-insensitive)
let vendor = null;
for (const item of items) {
  const row = item.json;
  if (row.Vendor && row.Vendor.toLowerCase() === searchName.toLowerCase()) {
    vendor = row;
    break;
  }
}

if (vendor) {
  return [{
    json: {
      chatId,
      status: 'found',
      searchName,
      vendor
    }
  }];
}

// Vendor not found - needs web search
return [{
  json: {
    chatId,
    status: 'not_found',
    searchName,
    defaultCity: dailyCity
  }
}];

const data = $input.first().json;
const chatId = data.chatId;
const vendor = data.vendor;
const isNewVendor = data.isNewVendor || false;

// --- Timezone handling: America/Chicago ---
const now = new Date();

const centralHour = parseInt(now.toLocaleString('en-US', { timeZone: 'America/Chicago', hour: 'numeric', hour12: false }));
const centralMinute = parseInt(now.toLocaleString('en-US', { timeZone: 'America/Chicago', minute: 'numeric' }));
const currentTimeStr = `${String(centralHour).padStart(2, '0')}:${String(centralMinute).padStart(2, '0')}`;

const centralDayOfWeek = new Date(
  now.toLocaleString('en-US', { timeZone: 'America/Chicago' })
).getDay();

const dayKeys = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

function timeToMinutes(timeStr) {
  const parts = timeStr.trim().split(':');
  return parseInt(parts[0]) * 60 + parseInt(parts[1]);
}

function formatTime12(timeStr) {
  const parts = timeStr.trim().split(':');
  let h = parseInt(parts[0]);
  const m = parts[1];
  const ampm = h >= 12 ? 'PM' : 'AM';
  if (h === 0) h = 12;
  else if (h > 12) h -= 12;
  return `${h}:${m} ${ampm}`;
}

function parseRanges(dayStr) {
  if (!dayStr || dayStr.trim().toLowerCase() === 'closed') return [];
  return dayStr.split(',').map(range => {
    const parts = range.trim().split('-');
    return { open: parts[0].trim(), close: parts[1].trim() };
  });
}

function formatDayRanges(dayStr) {
  if (!dayStr || dayStr.trim().toLowerCase() === 'closed') return 'Closed';
  const ranges = parseRanges(dayStr);
  return ranges.map(r => `${formatTime12(r.open)} - ${formatTime12(r.close)}`).join(', ');
}

function getDaySchedule(dayIndex) {
  const key = dayKeys[dayIndex];
  return (vendor[key] || '').trim();
}

const currentMinutes = timeToMinutes(currentTimeStr);
const todayStr = getDaySchedule(centralDayOfWeek);
const todayRanges = parseRanges(todayStr);
const todayName = dayNames[centralDayOfWeek];

let isOpenNow = false;
let currentRangeClose = null;
let nextRangeToday = null;
let statusText = '';

for (let i = 0; i < todayRanges.length; i++) {
  const range = todayRanges[i];
  const openMin = timeToMinutes(range.open);
  const closeMin = timeToMinutes(range.close);
  if (currentMinutes >= openMin && currentMinutes < closeMin) {
    isOpenNow = true;
    currentRangeClose = range.close;
    if (i + 1 < todayRanges.length) {
      nextRangeToday = todayRanges[i + 1];
    }
    break;
  }
  if (currentMinutes < openMin && !nextRangeToday) {
    nextRangeToday = range;
  }
}

if (todayRanges.length === 0) {
  statusText = `${vendor.Vendor} is *closed* all day today (${todayName}).`;
} else if (isOpenNow) {
  const closeMin = timeToMinutes(currentRangeClose);
  const minutesLeft = closeMin - currentMinutes;
  const hoursLeft = Math.floor(minutesLeft / 60);
  const minsLeft = minutesLeft % 60;
  let closesInStr = '';
  if (hoursLeft > 0 && minsLeft > 0) closesInStr = `${hoursLeft}h ${minsLeft}m`;
  else if (hoursLeft > 0) closesInStr = `${hoursLeft}h`;
  else closesInStr = `${minsLeft}m`;
  statusText = `${vendor.Vendor} is *open* right now! Closes in ${closesInStr} (at ${formatTime12(currentRangeClose)}).`;
  if (nextRangeToday) {
    statusText += ` Opens again at ${formatTime12(nextRangeToday.open)}.`;
  }
} else if (nextRangeToday) {
  const firstOpen = todayRanges[0];
  if (currentMinutes < timeToMinutes(firstOpen.open)) {
    statusText = `${vendor.Vendor} is *closed* right now. Opens today at ${formatTime12(nextRangeToday.open)}.`;
  } else {
    statusText = `${vendor.Vendor} is *closed* right now (on break). Opens again at ${formatTime12(nextRangeToday.open)}.`;
  }
} else {
  statusText = `${vendor.Vendor} is *closed* for today. Closed at ${formatTime12(todayRanges[todayRanges.length - 1].close)}.`;
}

let nextOpenLine = '';
if (!isOpenNow) {
  if (nextRangeToday) {
    nextOpenLine = `Next open: Today (${todayName}) at ${formatTime12(nextRangeToday.open)}`;
  } else {
    for (let offset = 1; offset <= 7; offset++) {
      const checkDayIndex = (centralDayOfWeek + offset) % 7;
      const checkStr = getDaySchedule(checkDayIndex);
      const checkRanges = parseRanges(checkStr);
      if (checkRanges.length > 0) {
        nextOpenLine = `Next open: ${dayNames[checkDayIndex]} at ${formatTime12(checkRanges[0].open)}`;
        break;
      }
    }
  }
  if (!nextOpenLine) {
    nextOpenLine = 'This vendor appears to have no open hours scheduled.';
  }
}

let weeklySchedule = '';
for (let d = 0; d < 7; d++) {
  const dayStr = getDaySchedule(d);
  const marker = (d === centralDayOfWeek) ? ' (today)' : '';
  weeklySchedule += `  ${dayNames[d]}${marker}: ${formatDayRanges(dayStr)}\n`;
}

const openIcon = isOpenNow ? '\u2705' : '\u274C';
const statusLabel = isOpenNow ? 'OPEN' : 'CLOSED';
let replyText = `${openIcon} *${vendor.Vendor}* - ${statusLabel}\n\n`;
replyText += `${statusText}\n\n`;
replyText += `*Today (${todayName}):* ${formatDayRanges(todayStr)}\n`;
if (nextOpenLine) replyText += `${nextOpenLine}\n`;

if (vendor.Location) {
  replyText += `\n\ud83d\udccd ${vendor.Location}\n`;
}

replyText += `\n*Weekly Hours:*\n${weeklySchedule}`;

const timeNowFormatted = formatTime12(currentTimeStr);
replyText += `\n_Checked at ${timeNowFormatted} CT_`;

if (isNewVendor) {
  replyText += '\n\n\ud83d\udcdd New vendor! Added to database for faster future lookups.';
}

return [{ json: { chatId, replyText } }];

const aiOutput = $input.first().json.output || '';
const chatId = $('Check Vendor Status').first().json.chatId;
const searchName = $('Check Vendor Status').first().json.searchName;
const defaultCity = $('Check Vendor Status').first().json.defaultCity || '';

let schedule = null;
try {
  schedule = JSON.parse(aiOutput);
} catch (e) {
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      schedule = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      schedule = null;
    }
  }
}

if (!schedule || schedule.error === 'not_found' || !schedule.vendor) {
  return [{
    json: {
      chatId,
      aiFound: false,
      replyText: `\u274C Could not find business hours for "${searchName}"${defaultCity ? ' in ' + defaultCity : ''}.\n\nTry using the vendor's official name (e.g., "Walgreens", "Target", "Costco").`
    }
  }];
}

const location = schedule.location || defaultCity;

const vendor = {
  Vendor: schedule.vendor,
  Location: location,
  Mon: schedule.Mon || 'Closed',
  Tue: schedule.Tue || 'Closed',
  Wed: schedule.Wed || 'Closed',
  Thu: schedule.Thu || 'Closed',
  Fri: schedule.Fri || 'Closed',
  Sat: schedule.Sat || 'Closed',
  Sun: schedule.Sun || 'Closed'
};

const sheetRow = [
  vendor.Vendor,
  vendor.Location,
  vendor.Mon,
  vendor.Tue,
  vendor.Wed,
  vendor.Thu,
  vendor.Fri,
  vendor.Sat,
  vendor.Sun
];

return [{
  json: {
    chatId,
    aiFound: true,
    isNewVendor: true,
    vendor,
    sheetRow
  }
}];

const data = $('Parse AI Response').first().json;
return [{
  json: {
    chatId: data.chatId,
    isNewVendor: true,
    vendor: data.vendor
  }
}];
